"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "„Yaban domuzları şalgamlarımı yiyor. Görürsen avla onları!“",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "„Hiç ejderha gördün mü? Lian, Ateş Dağı'nda olduğunu söylüyor.“",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "„Eskiden Kazehana sakin bir şehirdi. Sonra taşlar geldi.“",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "„Her taşın kendi ruhu var. Ve her biri geride başka bir şey bırakır.“",
