"Stadt · sicherer Ort": "Şehir · güvenli bölge",
"Lager · sicherer Ort": "Kamp · güvenli bölge",
"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "Yeşil Güneş Çayırları'yla büyük şehir Kazehana.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Haydutlar, örümcekler ve ayılarla dolu sık bir çam ormanı. Örümcek Mağarası ve Haydut Mahzeni.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Orkların ve akreplerin tozlu vadisi. Ork Kalesi.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Ogrelerin ve iblislerin gri kül ovası. Ölüler Mezarı.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "Buz kurtları, yetiler ve ayaz ruhlarıyla buzlu zirveler. Buz Mağarası.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Ölümsüzler, cadılar ve gullerle dolu sisli bataklık.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Kara bazalt ve lav nehirleri, golemler, ateş iblisleri ve ejderler. Ejder Yuvası.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Kendi etrafında dönersin, çevredeki tüm düşmanlara vurur ve onları kısa süre sersemletirsin.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Buff: Etrafında şimşekler çakar. Daha fazla saldırı ve hareket hızı.",
"Erdbeben": "Deprem",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Yere vurursun ve toprak sarsılır: Etrafındaki tüm düşmanlar {0} sn sersemler.",
"Starker Körper": "Güçlü Beden",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Buff: Bedenin taş gibi sertleşir. Daha fazla savunma, daha az alınan hasar.",
"Geistesschlag": "Zihin Darbesi",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Tek bir hedefe tüm gücünle yoğun bir darbe. Çok yüksek hasar.",
"Kriegsschrei": "Savaş Çığlığı",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Düşmanları felç eden bir çığlık: Yavaşlarlar ve daha fazla hasar alırlar.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "İki hançerinle dönerek etrafındaki tüm düşmanlara vurursun.",
"Schattensprung": "Gölge Sıçrayışı",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Gölgelerin içinden ileri sıçrar, yolundaki her şeyi kesersin.",
"Lähmende Klinge": "Felç Eden Bıçak",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Tendonlara bir saplama: Hedef {0} sn sersemler ve {1} sn zehirlenir.",
"Schattenmantel": "Gölge Pelerini",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Buff: Gölgeler seni sarar. Daha fazla kaçınma ve kritik vuruş.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Buff: Ejder gücü içine akar. Daha fazla saldırı ve beceri hasarı.",
"Geisterfaust": "Ruh Yumruğu",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Ruh gücünden bir yumruk bir hedefe vurur ve onu {0} sn sersemletir.",
"Windfessel": "Rüzgâr Bağı",
