"Wolfsplage": "Kurt Belası",
"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen.": "Kurtlar cesurlaşıyor. Kapıya varmadan sürüyü seyrelt.",
"Verirrte Hirsche": "Kaybolan Geyikler",
"Der Alpha": "Alfa",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel.": "Kurtların arkasında liderleri, alfa kurtlar var. Onlarsız sürü dağılır.",
