"Kapitel {0} · Dunkelwald": "Bölüm {0} · Karanlık Orman",
"Schützen im Dickicht": "Çalılıktaki Okçular",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter.": "Haydutlar ağaç tepelerinden kıpırdayan her şeye ok atıyor. İndir onları.",
"Netz der Spinnen": "Örümcek Ağı",
"Stein der Gier": "Açgözlülük Taşı",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie.": "İki Açgözlülük Taşı haydutları, altının hırsızları çektiği gibi çekiyor. Parçala onları.",
"Lautlose Jäger": "Sessiz Avcılar",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie.": "Vaşaklar gözcülerimizi kimse gelişlerini görmeden parçalıyor. Onlardan daha dikkatli ol.",
"Der Banditenfürst": "Haydut Lordu",
"Der Braunbär": "Boz Ayı",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig.": "Bir boz ayı sürüsü oduncu patikasını tuttu. Güçlüler, dikkatli ol.",
"Stein der Dornen": "Diken Taşı",
"Krieg in der Rostschlucht": "Pas Geçidi'nde Savaş",
"Orks vor der Talwacht": "Vadi Karakolu Önünde Orklar",
"Kapitel {0} · Rostschlucht": "Bölüm {0} · Pas Geçidi",
"Hyänen der Orks": "Orkların Sırtlanları",
"Die Schamanen": "Şamanlar",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut.": "Şamanları vadiye lanetler yağdırıyor. Onlarsız orklar cesaretini yitirir.",
"Stein der Schwärze": "Karalık Taşı",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen.": "Orklar kara taşlara tapıyor. Putlarını ellerinden al.",
"Stachel im Sand": "Kumdaki İğne",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten.": "Kaya yarıklarında dev akrepler yuva yapmış. Zehirleri bir öküzü felç eder. Yarıkları temizle.",
"Der Ork-Hauptmann": "Ork Yüzbaşı",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie.": "Yüzbaşıları olmadan orklar sadece vahşi bir sürü. Onları bul.",
"Stein der Asche": "Kül Taşı",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt.": "Kül Taşı vadiyi içten yakıyor. Geriye sadece toz kalmadan söndür onu.",
"Asche über dem Ödland": "Çorak Toprakların Üstünde Kül",
"Oger im Aschenfeld": "Kül Tarlasındaki Ogreler",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern.": "Thrak seni göndermekte haklıymış. Ogreler her gece kampımızı yağmalıyor. Uzak tut onları.",
"Kapitel {0} · Ödland": "Bölüm {0} · Çorak Topraklar",
"Wargrudel": "Varg Sürüsü",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel.": "Varglar ogreleri takip edip artıklarını yiyor. Sürüyü avla.",
"Dämonen im Ödland": "Çorak Topraklardaki İblisler",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe.": "Çorak Toprakların yarıklarından iblisler çıkıyor. Onları derinliklere geri sür.",
"Stein der Glut": "Kor Taşı",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus.": "Kor Taşları Çorak Toprakları yakıyor. Söndür onları.",
"Höllenhunde": "Cehennem Köpekleri",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen.": "Üç başlı köpekler yarıkları koruyor. Onları yenen yarıklara yaklaşabilir.",
"Die Oase im Süden": "Güneydeki Vaha",
"Kobras in der Wüste": "Çöldeki Kobralar",
"Kapitel {0} · Schlangental": "Bölüm {0} · Yılan Vadisi",
"Das Rasseln im Sand": "Kumdaki Çıngırak",
"Stein der Schatten": "Gölge Taşı",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder.": "Cengelde pitonlar koca öküzleri boğuyor. Orada odun kesen geri dönmüyor.",
"Schwarze Panther": "Kara Panterler",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher.": "Nagaların panterleri gece avlanıyor. Cengeli yeniden güvenli kıl.",
"Eis im Norden": "Kuzeyde Buz",
"Eiswölfe": "Buz Kurtları",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche.": "Seni Hakim mi gönderdi? Güzel. Buz kurtları kampımızın etrafında dolanıyor, her zaafın kokusunu alıyorlar.",
"Kapitel {0} · Frostgipfel": "Bölüm {0} · Ayaz Zirvesi",
"Der Yeti": "Yeti",
"Stein des Frostes": "Ayaz Taşı",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie.": "İki Ayaz Taşı zirvedeki buzun hiç erimemesine yol açıyor. Parçala onları.",
"Wilde Mammuts": "Vahşi Mamutlar",
"Frostgeister": "Ayaz Ruhları",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen.": "Kar fırtınalarında ruhlar dolaşır. Onlara dokunan içten donar.",
"Stein der Stille": "Sessizlik Taşı",
"Der Eiskönig": "Buz Kralı",
"Alles Eis gehorcht dem Eiskönig in der Eisgrotte. Bezwinge ihn, dann taut der Gipfel.": "Tüm buzlar Buz Mağarası'ndaki Buz Kralı'na itaat eder. Onu yen, zirve çözülsün.",
"Nebel über dem Moor": "Bataklığın Üstünde Sis",
"Das Totenmoor": "Ölüler Bataklığı",
"Kapitel {0} · Totenmoor": "Bölüm {0} · Ölüler Bataklığı",
"Moorwölfe": "Bataklık Kurtları",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest.": "Buradaki kurtlar yarı ölü ve avlanmayı bırakmıyorlar. İşlerini bitir.",
"Die Sumpfhexen": "Bataklık Cadıları",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu.": "Cadılar ölüleri çamurdan çağırıyor. Onlarsız mezarlar kapalı kalır.",
"Stein der Fäulnis": "Çürüme Taşı",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr.": "İki Çürüme Taşı suyu zehirliyor. Artık canlı hiçbir şey yetişmiyor.",
"Ghule": "Guller",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller.": "Guller cadıların uyandırdıklarını yiyor. Hızlı ve açlar. Daha hızlı ol.",
"Donner in der Klamm": "Kanyonda Gök Gürültüsü",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke.": "Seni Oswin mi gönderdi? Troller kanyonu kuşattı. Onlara gücümüzü göster.",
"Kapitel {0} · Donnerklamm": "Bölüm {0} · Gürleyen Kanyon",
"Harpyien": "Harpiler",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft.": "Harpiler geçide tırmanan herkese tepeden saldırıyor. İndir onları havadan.",
"Die Minotauren": "Minotorlar",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf.": "Minotorlar boynuzlarını eğip kapılarımıza saldırıyor. Durdur onları.",
"Stein der Pein": "Azap Taşı",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz.": "Kayalardan kan kırmızısı taşlar büyüyor. Acıyla besleniyorlar.",
"Erwachte Titanen": "Uyanan Titanlar",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer.": "Titan Sırtı'nda taş titanlar ayağa kalkıyor. Onları yeniden durdur – sonsuza dek.",
"Der Berg brennt": "Dağ Yanıyor",
"Lavagolems": "Lav Golemleri",
"Gunhild schickt dich? Dann bist du bereit. Golems aus Lava wälzen sich auf unser Lager zu.": "Seni Gunhild mi gönderdi? O hâlde hazırsın. Lavdan golemler kampımıza doğru yuvarlanıyor.",
"Kapitel {0} · Feuerberg": "Bölüm {0} · Ateş Dağı",
"Glutkatzen": "Kor Kedileri",
"Glutkatzen streifen durch die Lavafelder. Wo sie laufen, brennt der Boden.": "Kor kedileri lav tarlalarında dolaşıyor. Geçtikleri yerde toprak yanıyor.",
"Stein der Flamme": "Alev Taşı",
"Zwei Steine der Flamme heizen den Berg an. Ohne sie verlöschen die Lavaflüsse.": "İki Alev Taşı dağı ısıtıyor. Onlar olmadan lav nehirleri söner.",
"Feuerdämonen": "Ateş İblisleri",
