"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Köpekler gider gitmez tilkiler ahırların etrafında dolanıyor. Onları çayırlara geri kovala",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Yaban domuzları köylülerin hasadını yiyor. Erzaksız bir kış sonumuz olur",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Çayırların kenarında bir öfke taşı parlıyor. Öfkesi hayvanları çıldırtıyor – onu parçala",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "İyi ki Bao seni gönderdi. Haydutlar orman yolundaki her tüccara saldırıyor. Onları kovala",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Buradaki yaban domuzlarının kılları yerine dikenleri var. Tuzaklarımızı – ve tuzakçıları – parçalıyorlar",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "Ormanın derinliklerinde dev örümcekler yolların üstüne ağ örüyor. Gerekirse yak",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "Ormanın ortasında bir diken taşı büyüyor. Dikenli dalları her ağacı boğuyor. Onu yok et",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Seni Hagen mi gönderdi? Gel o zaman, orklar çoktan çitlerimizin önünde. Ordularını zayıflat",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Orklar sırtlanları köpek gibi besleyip izcilerimize saldırtıyor. Sürüyü temizle",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Seni İdris mi gönderdi? Tanrılar Sahra'ya iyi davranıyor. Kobralar her su başında pusuda",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Şu tıkırtıyı duyuyor musun? Çıngıraklı yılanlar. Yüzlercesi. Kervanlar artık yola çıkmaya cesaret edemiyor",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Ayaz Zirvesi'nde ev büyüklüğünde yetiler görülmüş. Kanıt olarak postlarını getir",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Ayaz geçmediğinden beri mamutlar çılgına döndü. Erzak kulübelerimizi eziyorlar",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Sessizlik taşının olduğu yerde her şarkı susar. Sesi zirveye geri getir",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "Ruh taşlarının sonuncusu ve en güçlüsü. Onu yok et, taşlar büyümeyi bıraksın",
