"Die Turnierarena ist leer. Du kehrst zum Turniermeister zurück": "Turnuva arenası boş. Turnuva Ustasına dönüyorsun",
"Ohne Verbindung zum Kanal endet das Spiel in der Turnierarena (ohne Wertung).": "Kanal bağlantısı olmadan turnuva arenasındaki maç biter (puansız).",
"Wer fällt, scheidet aus – das letzte Team gewinnt": "Düşen elenir – son kalan takım kazanır",
"Ende": "Son",
"Ausgeschieden – du schaust zu": "Elendin – izliyorsun",
"Zurück in die Stadt": "Şehre dön",
"Wer geht, verliert den Rangkampf": "Ayrılan dereceli dövüşü kaybeder",
"Ergebnis der Turnierarena": "Turnuva arenası sonucu",
"Das letzte Team steht": "Son takım ayakta",
"Die Zeit ist um": "Süre doldu",
"Der Turm ist voll geladen": "Kule tamamen doldu",
"Das andere Team hat die Arena verlassen": "Diğer takım arenadan ayrıldı",
"Beide Teams sind gefallen": "İki takım da düştü",
"Kills": "Öldürme",
"Die Turmschlacht zählt nicht für den Rang – nur für den Spaß": "Kule savaşı rütbeye sayılmaz – sadece eğlence için",
"Du kämpfst gerade in der Turnierarena": "Zaten turnuva arenasında savaşıyorsun",
"läuft gerade": "sürüyor",
"Deine Gruppe kämpft im selben Team, wenn ihr euch für dieselbe Art anmeldet": "Aynı türe kaydolursanız grubun aynı takımda savaşır",
"Die Oasenstadt Sahra, darum eine heiße Wüste voller Schlangen, außen der Dschungel der Nagas": "Sahra vaha şehri, etrafında yılanlarla dolu sıcak bir çöl, dışında nagaların ormanı",
"Die Klammfeste, darum eine tiefe Felsschlucht mit Trollen und Minotauren, außen der Kamm der Titanen": "Boğaz kalesi, etrafında troller ve minotorlarla dolu derin bir kanyon, dışında titanların sırtı",
"Verkohlter Wald voller Glut, Aschenräuber, Spinnen und Kohlenbären. Spinnenhöhle und Banditenkeller": "Korla, kül yağmacılarıyla, örümceklerle ve kömür ayılarıyla dolu kömürleşmiş orman. Örümcek Mağarası ve Haydut Mahzeni",
"Bleicher Sand voller alter Gebeine, Beinbrecher und Skorpionen. Orkfestung": "Eski kemikler, kemik kıranlar ve akreplerle dolu solgun kum. Ork Kalesi",
"Rote Steppe unter dunklem Himmel mit Blutogern und Blutdämonen. Totengruft": "Kan ogreleri ve kan iblisleriyle karanlık gökyüzü altında kızıl bozkır. Ölüler Mahzeni",
"Ewige Winternacht mit Mitternachtswölfen, Dunkelyetis und Frostgespenstern. Eisgrotte": "Gece yarısı kurtları, karanlık yetiler ve ayaz hortlaklarıyla sonsuz kış gecesi. Buz Mağarası",
